What is the output of the following recursive function?
int func(int n) {
if(n == 0) return 0;
if(n == 1) return 1;
if(n % 2 == 0)
return func(n/2);
else
return func(n/2) + func(n/2 + 1);
}
cout << func(7);

What does the following code output?
#include <iostream>
using namespace std;
void increment(int arr[], int size) {
for(int i=0;i<size;i++)
(*(arr+i))++;
}
int main() {
int data[3] = {2,4,6};
increment(data,3);
cout << data[0] << " " << data[1] << " " << data[2];
return 0;
}

